questions.referenceSql:
DELIMITER $$
CREATE PROCEDURE p_credit_total(IN p_sno CHAR(8), OUT p_credit INT)
BEGIN
 SELECT COALESCE(SUM(c.Credit),0) INTO p_credit FROM sc x JOIN course c ON c.Cno=x.Cno WHERE x.Sno=p_sno AND x.Grade>=60;
END$$
DELIMITER ;
